function notify(text){$('notice').textContent=text;$('notice').hidden=!text;}
function numeric(value){if(typeof value==='number')return Number.isFinite(value)?value:NaN;let s=String(value??'').trim();if(!s)return NaN;let negative=/^\(.*\)$/.test(s);s=s.replace(/[\s,$£€¥₹()%]/g,'');if(!/^[+-]?(?:\d+\.?\d*|\.\d+)(?:e[+-]?\d+)?$/i.test(s))return NaN;const n=Number(s);return negative?-Math.abs(n):n;}
function dateKey(value){if(!value)return '';let s=String(value).trim(),m=s.match(/^(\d{4})[-/](\d{1,2})(?:[-/](\d{1,2}))?(?:[T\s].*)?$/);if(m){let y=+m[1],mo=+m[2],d=+(m[3]||1);if(mo<1||mo>12||d<1||d>new Date(y,mo,0).getDate())return '';return `${y}-${String(mo).padStart(2,'0')}`;}m=s.match(/^(\d{1,2})[/-](\d{1,2})[/-](\d{4})(?:[T\s].*)?$/);if(m){const mo=+m[1],day=+m[2],year=+m[3];if(mo<1||mo>12||day<1||day>new Date(year,mo,0).getDate())return '';return year+'-'+String(mo).padStart(2,'0');}if(/^\d+$/.test(s))return '';const d=new Date(s);return isNaN(d)?'':`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;}
function sample(){const products=[['Studio headphones',249,0.31],['Ergonomic chair',389,0.27],['4K monitor',429,0.23],['Mechanical keyboard',129,0.35],['Standing desk',599,0.22],['Portable SSD',119,0.28],['Wireless mouse',59,0.39],['Webcam Pro',99,0.24],['Desk lamp',69,0.29],['USB-C dock',149,0.2],['Laptop stand',49,0.32],['Smart speaker',89,0.13],['Tablet sleeve',29,0.23],['Travel adapter',35,0.17],['Screen protector',19,0.15],['Cable organizer',15,0.12],['Bluetooth speaker',79,-0.09],['Phone charger',39,-0.16],['Fitness tracker',99,-0.21],['Budget earbuds',29,-0.34]];let rows=[];products.forEach(([product,price,margin],i)=>{for(let month=1;month<=12;month++){let qty=9+((i*17+month*13)%37);if(i<5)qty*=2;let sales=Math.round(price*qty*(0.83+month*.025));let profit=Math.round(sales*margin*(.86+((i+month)%5)*.07));rows.push({product,sales,profit,region:['North America','Europe','Asia Pacific','Latin America'][(i+month)%4],month:`2025-${String(month).padStart(2,'0')}`});}});const existing=datasets.find(d=>d.demo);if(existing){activateDataset(existing.id);return;}addDataset('Sample portfolio',rows,true);}
function initFilters(){const populate=(id,values,all)=>{const el=$(id);el.replaceChildren(new Option(all,''));values.forEach(v=>el.add(new Option(v,v)));};populate('regionFilter',[...new Set(records.map(r=>r.region).filter(Boolean))].sort(),'All regions');populate('yearFilter',[...new Set(records.map(r=>r.month.slice(0,4)).filter(Boolean))].sort(),'All time');$('regionFilter').disabled=!records.some(r=>r.region);$('yearFilter').disabled=!records.some(r=>r.month);for(const [id,key,all] of [['categoryFilter','category','All categories'],['subcategoryFilter','subcategory','All sub-categories'],['segmentFilter','segment','All segments']]){populate(id,[...new Set(records.map(r=>r[key]).filter(Boolean))].sort(),all);$(id).disabled=!records.some(r=>r[key]);}for(const option of $('groupBy').options){option.disabled=option.value!=='product'&&!records.some(r=>r[option.value]);}if(!$('groupBy').value||!records.some(r=>r[$('groupBy').value]))$('groupBy').value='product';}
function aggregate(rows,key){const map=new Map();rows.forEach(r=>{let k=r[key];if(!k)return;if(!map.has(k))map.set(k,{name:k,sales:0,profit:0,count:0});let a=map.get(k);a.sales+=r.sales;a.profit+=r.profit;a.count++;});return [...map.values()];}
const quadrantPlugin={id:'quadrants',beforeDraw(chart){if(chart.canvas.id!=='bubbleChart')return;const {ctx,chartArea:a,scales:{x,y}}=chart;if(!a)return;const split=chart.$split||0,x0=Math.max(a.left,Math.min(a.right,x.getPixelForValue(split))),y0=Math.max(a.top,Math.min(a.bottom,y.getPixelForValue(0)));ctx.save();const rect=(left,top,w,h,color)=>{ctx.fillStyle=color;ctx.fillRect(left,top,Math.max(0,w),Math.max(0,h));};rect(a.left,a.top,x0-a.left,y0-a.top,'#54d6b306');rect(x0,a.top,a.right-x0,y0-a.top,'#ac99ff08');rect(a.left,y0,x0-a.left,a.bottom-y0,'#edbd6c06');rect(x0,y0,a.right-x0,a.bottom-y0,'#ef839506');ctx.setLineDash([4,5]);ctx.strokeStyle='#73708455';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(x0,a.top);ctx.lineTo(x0,a.bottom);ctx.moveTo(a.left,y0);ctx.lineTo(a.right,y0);ctx.stroke();ctx.setLineDash([]);ctx.font='600 9px "DM Sans",sans-serif';ctx.textBaseline='top';ctx.fillStyle='#54d6b398';ctx.fillText('CASH COWS',a.left+12,a.top+12);ctx.fillStyle='#ac99ffb0';ctx.textAlign='right';ctx.fillText('STARS',a.right-12,a.top+12);ctx.fillStyle='#ef8395a0';ctx.textBaseline='bottom';ctx.fillText('LOSS-MAKERS',a.right-12,a.bottom-10);ctx.textAlign='left';ctx.fillStyle='#edbd6c99';ctx.fillText('QUESTION MARKS',a.left+12,a.bottom-10);ctx.restore();}};
function buildChart(id,type,data,options,extra={}){if(options.indexAxis==='y'){options.scales.y.ticks.callback=function(v){const name=String(this.getLabelForValue(v));return name.length>32?name.slice(0,30)+'…':name;};options.scales.y.afterFit=axis=>{axis.width=Math.min(axis.width,155);};}if(charts[id])charts[id].destroy();charts[id]=new Chart($(id),{type,data,options,plugins:id==='bubbleChart'?[quadrantPlugin]:[]});Object.assign(charts[id],extra);charts[id].update();}
function chartOptions(horizontal=false){return {responsive:true,maintainAspectRatio:false,animation:{duration:650},indexAxis:horizontal?'y':'x',layout:{padding:{right:10}},plugins:{legend:{display:false},tooltip:{backgroundColor:'#242634',borderColor:'#454255',borderWidth:1,titleColor:'#eeeaf8',bodyColor:'#bfc2d3',padding:12,displayColors:false,callbacks:{label:c=>' Profit: '+fmt(horizontal?c.parsed.x:c.parsed.y)}}},scales:{x:{border:{display:false},grid:{color:'#282c3770',drawTicks:false},ticks:{color:'#747c91',font:{size:9},padding:10,callback:horizontal?v=>compact(v):undefined}},y:{border:{display:false},grid:{display:!horizontal,color:'#282c3770',drawTicks:false},ticks:{color:horizontal?'#a8adc0':'#747c91',font:{size:9},padding:10,callback:horizontal?undefined:v=>compact(v)}}}};}
function render(){updateGroupingContext();if(comparing){renderComparison();return;}if(typeof Chart==='undefined'){notify('Chart.js could not load. Check your internet connection and refresh.');return;}Chart.defaults.font.family="'DM Sans', sans-serif";const rows=filteredRows(records);const current=datasets.find(d=>d.id===activeId);if(current)renderWorldMap([{...current,rows}], 'singleWorldMap','singleWorldMapStatus');const products=aggregate(rows,'product').sort((a,b)=>b.profit-a.profit),regions=aggregate(rows,'region').sort((a,b)=>b.profit-a.profit),months=aggregate(rows,'month').sort((a,b)=>a.name.localeCompare(b.name));let sales=rows.reduce((a,r)=>a+r.sales,0),profit=rows.reduce((a,r)=>a+r.profit,0),margin=sales?profit/sales*100:0;const mean=products.length?sales/products.length:0;products.forEach(p=>p.group=p.profit>=0?(p.sales>=mean?'star':'cow'):(p.sales<mean?'question':'loss'));
$('datasetName').textContent=currentName;$('datasetBadge').textContent=isDemo?'DEMO DATA':'YOUR DATA';$('rowCount').textContent=rows.length.toLocaleString()+' transactions';$('revenue').textContent=fmt(sales);$('profit').textContent=fmt(profit);$('profit').style.color=profit<0?'#ef8395':'';$('margin').textContent=sales?margin.toFixed(1)+'%':'—';$('marginBar').style.width=Math.max(0,Math.min(100,margin))+'%';$('productCount').textContent=products.length+' groups';$('profitableCount').textContent=products.filter(p=>p.profit>0).length+' profitable groups';
const maxSales=Math.max(1,...products.map(p=>Math.abs(p.sales)));let bubbleOptions=chartOptions();bubbleOptions.scales.x.title={display:true,text:'SALES ($)',color:'#777f93',font:{size:9},padding:10};bubbleOptions.scales.y.title={display:true,text:'PROFIT ($)',color:'#777f93',font:{size:9},padding:8};bubbleOptions.scales.x.ticks.callback=v=>compact(v);bubbleOptions.scales.x.min=Math.min(0,...products.map(p=>p.sales))*1.15;bubbleOptions.scales.x.suggestedMax=maxSales*1.17;bubbleOptions.scales.y.suggestedMin=Math.min(-Math.max(1,...products.map(p=>Math.abs(p.profit)))*.25,...products.map(p=>p.profit*1.4));bubbleOptions.scales.y.suggestedMax=Math.max(1,...products.map(p=>p.profit))*1.35;bubbleOptions.plugins.tooltip.callbacks={title:items=>items[0]?.raw.name||'',label:c=>['Revenue: '+fmt(c.raw.x),'Profit: '+fmt(c.raw.y),'Margin: '+(c.raw.x?(c.raw.y/c.raw.x*100).toFixed(1)+'%':'N/A')]};buildChart('bubbleChart','bubble',{datasets:[{data:products.map(p=>({x:p.sales,y:p.profit,r:5+Math.sqrt(Math.abs(p.sales)/maxSales)*19,name:p.name})),backgroundColor:products.map(p=>colors[p.group]+'9c'),borderColor:products.map(p=>colors[p.group]),borderWidth:1.5,hoverBorderWidth:3}]},bubbleOptions,{$split:mean});
const bars=(id,list,color)=>{let opts=chartOptions(true);opts.scales.x.beginAtZero=true;buildChart(id,'bar',{labels:list.map(p=>p.name),datasets:[{data:list.map(p=>p.profit),backgroundColor:list.map(p=>p.profit<0?'#ef8395b3':color),hoverBackgroundColor:list.map(p=>p.profit<0?'#ef8395':color),borderRadius:4,barThickness:12}]},opts);};bars('topChart',products.slice(0,10),'#54d6b3b8');bars('bottomChart',products.slice().reverse().slice(0,10),'#ac99ffad');
let ro=chartOptions();ro.scales.y.beginAtZero=true;buildChart('regionChart','bar',{labels:regions.map(r=>r.name),datasets:[{data:regions.map(r=>r.profit),backgroundColor:regions.map((r,i)=>r.profit<0?'#ef8395b0':['#ac99ffb8','#9985e5a0','#8371c68c','#6e5da777'][i%4]),borderRadius:5,maxBarThickness:55}]},ro);$('regionEmpty').hidden=!!regions.length;
let mo=chartOptions();mo.scales.y.beginAtZero=true;mo.scales.x.ticks.maxTicksLimit=12;buildChart('monthChart','bar',{labels:months.map(m=>new Date(m.name+'-01T12:00:00').toLocaleDateString('en-US',{month:'short',...(new Set(months.map(x=>x.name.slice(0,4))).size>1?{year:'2-digit'}:{})})),datasets:[{data:months.map(m=>m.profit),backgroundColor:months.map(m=>m.profit<0?'#ef8395b0':'#8e9feeab'),borderRadius:4,maxBarThickness:26}]},mo);$('monthEmpty').hidden=!!months.length;
if(!products.length){$('summary').innerHTML='<div><h3>No transactions in this view</h3><p>Try resetting the filters to explore your portfolio.</p></div>';return;}const top=products[0],losses=products.filter(p=>p.profit<0),loss=losses.reduce((n,p)=>n+p.profit,0),stars=products.filter(p=>p.group==='star').length;let bestRegion=regions[0],bestMonth=months.slice().sort((a,b)=>b.profit-a.profit)[0];$('summary').innerHTML=`<div><h3>01 / ${top.profit>0?'Back your best performer':'Review your strongest product'}</h3><p><b>${esc(top.name)}</b> ${top.profit>0?'leads your portfolio with':'has the highest profit at'} <b>${fmt(top.profit)}</b>. ${stars} ${stars===1?'group is a Star':'groups are Stars'} — at or above average revenue with non-negative profit.</p></div><div><h3>02 / ${losses.length?'Stop the profit leaks':'Keep the momentum'}</h3><p>${losses.length?`<b>${losses.length} groups</b> are unprofitable, with combined losses of <b>${fmt(Math.abs(loss))}</b>. Review pricing, discounts, and costs, starting with <b>${esc(products[products.length-1].name)}</b>.`:'No groups are loss-making in this view. Protect your margins as you scale your strongest sellers.'}</p></div><div><h3>03 / Find your next opportunity</h3><p>${bestRegion?`<b>${esc(bestRegion.name)}</b> is your top region at <b>${fmt(bestRegion.profit)}</b> profit. `:''}${bestMonth?`<b>${new Date(bestMonth.name+'-01T12:00:00').toLocaleDateString('en-US',{month:'long',year:'numeric'})}</b> was your strongest month with <b>${fmt(bestMonth.profit)}</b>.`: 'Map a date column to uncover monthly performance patterns.'}</p></div>`;}
function openMapping(results,filename){const headers=results.meta.fields||[];if(!headers.length||!results.data.length){notify('This CSV is empty or has no readable column headers.');return;}pending={data:results.data,headers,filename};const definitions=[['product','Product / Item *',/^(product|product name|category|item|item name|sku)$/i],['sales','Sales / Revenue *',/^(sales|revenue|total sales|amount|sales amount)$/i],['profit','Profit *',/^(profit|net profit|gross profit|total profit)$/i],['region','Region',/^(region|country|territory|market|location)$/i],['date','Order date',/^(date|order date|sale date|sales date|month|transaction date)$/i],['category','Category (optional)',/^category$/i],['subcategory','Sub-category (optional)',/^sub[ -]?category$/i],['segment','Customer segment (optional)',/^(segment|customer segment)$/i],['country','Country (for geography)',/^(country|country name)$/i]];$('mappingFields').replaceChildren();definitions.forEach(([key,title,re])=>{const label=document.createElement('label');label.textContent=title;const select=document.createElement('select');select.id='map_'+key;select.add(new Option(!['product','sales','profit'].includes(key)?'Not mapped':'Select a column',''));headers.forEach(h=>select.add(new Option(h,h)));const priority={product:['product name','product','item name','item','sku','category'],date:['order date','date','sale date','sales date','transaction date','month'],region:['region','territory','market','country','location']};select.value=(priority[key]||[]).map(n=>headers.find(h=>h.toLowerCase().trim()===n)).find(Boolean)||headers.find(h=>re.test(h.trim()))||'';if(key==='category'&&select.value===$('map_product')?.value)select.value='';label.append(select);$('mappingFields').append(label);});$('mappingInfo').textContent=`${filename} · ${results.data.length.toLocaleString()} rows · ${headers.length} columns. Dates: ISO recommended; ambiguous dates use month/day.`;$('mapping').hidden=false;notify('');$('mapping').scrollIntoView({behavior:'smooth',block:'center'});}
$('uploadBtn').onclick=()=>$('fileInput').click();
$('addFiles').onclick=()=>$('fileInput').click();
$('fileInput').onchange=e=>{importQueue.push(...Array.from(e.target.files));e.target.value='';if(!importing)nextImport();};
async function nextImport(){pending=null;$('mapping').hidden=true;const file=importQueue.shift();if(!file){importing=false;return;}importing=true;if(typeof Papa==='undefined'){notify('CSV parser could not load. Check your connection and refresh.');importQueue=[];importing=false;return;}let csvText;try{const bytes=await file.arrayBuffer();try{csvText=new TextDecoder('utf-8',{fatal:true}).decode(bytes);}catch{csvText=new TextDecoder('windows-1252').decode(bytes);}}catch(error){nextImport();notify('Unable to read '+file.name+': '+error.message);return;}Papa.parse(csvText,{header:true,skipEmptyLines:'greedy',transformHeader:h=>h.replace(/^\uFEFF/,'').trim(),complete:result=>{if(result.errors.some(e=>e.type==='Quotes')||!result.meta.fields?.length||!result.data.length){nextImport();notify(file.name+': empty or malformed CSV; skipped.');return;}openMapping(result,file.name);$('mappingTitle').textContent='Map '+file.name;$('mappingInfo').textContent+=(importQueue.length?' · '+importQueue.length+' more files waiting':'');},error:error=>{nextImport();notify(file.name+': '+error.message);}});}
$('applyMapping').onclick=()=>{if(!pending)return;const mapping=Object.fromEntries(['product','sales','profit','region','date','category','subcategory','segment','country'].map(k=>[k,$('map_'+k).value]));if(!mapping.product||!mapping.sales||!mapping.profit){notify('Please select a product/category, sales, and profit column.');return;}const selected=Object.values(mapping).filter(Boolean);if(new Set(selected).size!==selected.length){notify('Choose a different column for each field.');return;}let skipped=0,invalidDates=0;const parsed=[];pending.data.forEach(r=>{const product=String(r[mapping.product]??'').trim(),sales=numeric(r[mapping.sales]),profit=numeric(r[mapping.profit]);if(!product||!Number.isFinite(sales)||!Number.isFinite(profit)){skipped++;return;}const month=mapping.date?dateKey(r[mapping.date]):'';if(mapping.date&&!month)invalidDates++;parsed.push({product,sales,profit,region:mapping.region?String(r[mapping.region]??'').trim()||'Unspecified':'',month,category:mapping.category?String(r[mapping.category]??'').trim():'',subcategory:mapping.subcategory?String(r[mapping.subcategory]??'').trim():'',segment:mapping.segment?String(r[mapping.segment]??'').trim():'',country:mapping.country?String(r[mapping.country]??'').trim():''});});if(!parsed.length){notify('No valid transactions found. Check your mapping and numeric values.');return;}const importedName=pending.filename;pending=null;$('mapping').hidden=true;addDataset(importedName,parsed,false);nextImport();notify([skipped?`${skipped} rows skipped because product, sales, or profit was missing or invalid.`:'',invalidDates?`${invalidDates} rows have unrecognized dates and are excluded from the monthly chart (but included in totals).`:''].filter(Boolean).join(' '));};$('cancelMapping').onclick=()=>{notify('');nextImport();};$('sampleBtn').onclick=sample;$('regionFilter').onchange=render;$('yearFilter').onchange=render;$('resetFilters').onclick=()=>{for(const id of ['regionFilter','yearFilter','categoryFilter','subcategoryFilter','segmentFilter'])$(id).value='';render();};

function addDataset(name,rows,demo){const d={id:nextId++,name,rows,demo,color:fileColors[datasets.length%fileColors.length]};datasets.push(d);activateDataset(d.id);}
function activateDataset(id){const d=datasets.find(x=>x.id===id);if(!d)return;activeId=id;records=d.rows;currentName=d.name;isDemo=d.demo;comparing=false;$('singleAnalysis').hidden=false;$('comparison').hidden=true;initFilters();renderLibrary();render();}
function renderLibrary(){const list=$('datasetList');list.replaceChildren();datasets.forEach(d=>{const item=document.createElement('div');item.className='dataset-item'+(!comparing&&activeId===d.id?' current':'');const checkbox=document.createElement('input');checkbox.type='checkbox';checkbox.checked=selectedIds.has(d.id);checkbox.setAttribute('aria-label','Select '+d.name+' for comparison');checkbox.onchange=()=>{checkbox.checked?selectedIds.add(d.id):selectedIds.delete(d.id);renderLibrary();};const open=document.createElement('button');open.className='dataset-open';open.title='Analyze '+d.name;open.innerHTML=`<span class="dataset-label">${esc(d.name)}</span><small>${d.rows.length.toLocaleString()} rows${d.demo?' · sample':''}</small>`;open.onclick=()=>activateDataset(d.id);const dot=document.createElement('span');dot.className='dataset-color';dot.style.background=d.color;item.append(checkbox,dot,open);list.append(item);});$('pairCompareBtn').disabled=datasets.length<2;$('compareBtn').disabled=selectedIds.size<2;$('compareBtn').textContent=`Compare selected (${selectedIds.size})`;}
$('compareBtn').onclick=()=>{if(selectedIds.size<2)return;comparing=true;comparisonIds=new Set(selectedIds);records=datasets.filter(d=>comparisonIds.has(d.id)).flatMap(d=>d.rows);initFilters();$('singleAnalysis').hidden=true;$('comparison').hidden=false;renderLibrary();render();};
$('exitCompare').onclick=()=>activateDataset(activeId);
function renderComparison(){if(typeof Chart==='undefined'){notify('Chart.js could not load. Check your internet connection and refresh.');return;}const chosen=[...comparisonIds].map(id=>datasets.find(d=>d.id===id)).filter(Boolean);const stats=chosen.map(d=>{const rows=filteredRows(d.rows);const sales=rows.reduce((n,r)=>n+r.sales,0),profit=rows.reduce((n,r)=>n+r.profit,0);return {...d,rows,sales,profit,margin:sales?profit/sales*100:null,products:aggregate(rows,'product'),regions:aggregate(rows,'region'),months:aggregate(rows,'month')};});$('comparisonTitle').textContent=chosen.length===2?`${displayName(chosen[0].name)} vs ${displayName(chosen[1].name)}`:`Comparing ${chosen.length} portfolios`;renderPair(stats);renderWorldMap(stats);$('datasetName').textContent=chosen.length+' files selected';$('datasetBadge').textContent='COMPARISON';$('rowCount').textContent=stats.reduce((n,s)=>n+s.rows.length,0).toLocaleString()+' transactions across files';$('comparisonRows').innerHTML=stats.map(d=>`<tr><td><i class="dataset-color" style="background:${d.color}"></i>${esc(d.name)}</td><td>${d.rows.length.toLocaleString()}</td><td>${fmt(d.sales)}</td><td class="${d.profit<0?'negative':''}">${fmt(d.profit)}</td><td>${d.margin===null?'—':d.margin.toFixed(1)+'%'}</td></tr>`).join('');
const options=()=>{const o=chartOptions();o.scales.y.beginAtZero=true;o.plugins.legend={display:true,position:'bottom',labels:{color:'#adb1c5',boxWidth:9,boxHeight:9,padding:16,font:{size:10}}};o.plugins.tooltip.callbacks={label:c=>c.dataset.label+': '+(c.parsed.y===null?'No data':fmt(c.parsed.y))};return o;};
buildChart('compareTotals','bar',{labels:stats.map(d=>d.name),datasets:[{label:'Revenue',data:stats.map(d=>d.sales),backgroundColor:'#ac99ffb0',borderRadius:4},{label:'Profit',data:stats.map(d=>d.profit),backgroundColor:'#54d6b3b0',borderRadius:4}]},options());
function grouped(id,key,labels){const o=options();o.scales.x.ticks.maxTicksLimit=12;const display=key==='months'?labels.map(k=>new Date(k+'-01T12:00:00').toLocaleDateString('en-US',{month:'short',year:'2-digit'})):labels;buildChart(id,'bar',{labels:display,datasets:stats.map(d=>{const map=new Map(d[key].map(r=>[r.name,r.profit]));return {label:d.name,data:labels.map(k=>map.has(k)?map.get(k):null),backgroundColor:d.color+'b8',borderColor:d.color,borderRadius:3,maxBarThickness:32};})},o);}
const totals=new Map();stats.forEach(d=>d.products.forEach(p=>totals.set(p.name,(totals.get(p.name)||0)+p.profit)));const productLabels=[...totals].sort((a,b)=>b[1]-a[1]).slice(0,10).map(x=>x[0]);grouped('compareProducts','products',productLabels);grouped('compareRegions','regions',[...new Set(stats.flatMap(d=>d.regions.map(r=>r.name)))].sort());grouped('compareMonths','months',[...new Set(stats.flatMap(d=>d.months.map(r=>r.name)))].sort());
const valid=stats.filter(d=>d.rows.length);if(!valid.length){$('comparisonSummary').innerHTML='<div><h3>No matching transactions</h3><p>Reset the region or period filters to compare these files.</p></div>';return;}const leader=valid.slice().sort((a,b)=>b.profit-a.profit)[0],margins=valid.filter(d=>d.margin!==null).sort((a,b)=>b.margin-a.margin),bestMargin=margins[0];let difference='';if(valid.length===2){const other=valid.find(d=>d.id!==leader.id);difference=` That is <b>${fmt(leader.profit-other.profit)}</b> more than <b>${esc(other.name)}</b>.`;}const lackingRegion=stats.filter(d=>!d.regions.length).length,lackingMonth=stats.filter(d=>!d.months.length).length;$('comparisonSummary').innerHTML=`<div><h3>01 / Highest profit</h3><p><b>${esc(leader.name)}</b> has the highest profit at <b>${fmt(leader.profit)}</b>.${difference}</p></div><div><h3>02 / Margin efficiency</h3><p>${bestMargin?`<b>${esc(bestMargin.name)}</b> has the highest margin at <b>${bestMargin.margin.toFixed(1)}%</b>. ${margins.length>1?'The spread between highest and lowest is <b>'+(bestMargin.margin-margins[margins.length-1].margin).toFixed(1)+' percentage points</b>.':''}`:'Margins cannot be calculated when revenue is zero.'}</p></div><div><h3>03 / Compare like for like</h3><p>Files are not deduplicated. Product and region names match exactly. ${lackingRegion?lackingRegion+' file(s) have no regional data in this view. ':''}${lackingMonth?lackingMonth+' file(s) have no monthly data in this view. ':''}Use matching currencies and periods for a meaningful comparison.</p></div>`;}

function displayName(name){return name.replace(/\.csv$/i,'').replace(/_/g,' ').replace(/\b[a-z]/g,c=>c.toUpperCase());}
function openPair(left,right){if(left===right||!datasets.some(d=>d.id===left)||!datasets.some(d=>d.id===right))return;selectedIds=new Set([left,right]);$('compareBtn').onclick();}
$('pairCompareBtn').onclick=()=>{const checked=[...selectedIds];const left=checked.length===2?checked[0]:activeId;const right=checked.length===2?checked[1]:(datasets.find(d=>d.id!==left&&!d.demo)||datasets.find(d=>d.id!==left)).id;openPair(left,right);};
$('leftDataset').onchange=()=>{const old=[...comparisonIds];const left=Number($('leftDataset').value);openPair(left,left===old[1]?old[0]:old[1]);};
$('rightDataset').onchange=()=>{const old=[...comparisonIds];const right=Number($('rightDataset').value);openPair(right===old[0]?old[1]:old[0],right);};
$('swapPair').onclick=()=>{const [a,b]=comparisonIds;openPair(b,a);};
function renderPair(stats){$('pairView').hidden=stats.length!==2;if(stats.length!==2)return;const [a,b]=stats;['leftDataset','rightDataset'].forEach((id,i)=>{const select=$(id);select.replaceChildren();datasets.forEach(d=>select.add(new Option(displayName(d.name),String(d.id))));select.value=String(stats[i].id);});
const delta=(key,percent=false)=>{if(!a.rows.length||!b.rows.length||a[key]===null||b[key]===null)return 'Not comparable';const n=b[key]-a[key];return (n>0?'+':n<0?'−':'')+(percent?Math.abs(n).toFixed(1)+' pp':fmt(Math.abs(n)));};$('pairDelta').innerHTML=`<span><b>B − A</b> · Right compared with left</span><span>Revenue <strong>${delta('sales')}</strong></span><span>Profit <strong>${delta('profit')}</strong></span><span>Margin <strong>${delta('margin',true)}</strong></span>`;
const totals=new Map();stats.forEach(d=>d.products.forEach(p=>totals.set(p.name,(totals.get(p.name)||0)+p.profit)));const names=[...totals].sort((x,y)=>y[1]-x[1]).slice(0,10).map(x=>x[0]);const months=[...new Set(stats.flatMap(d=>d.months.map(m=>m.name)))].sort();const values=key=>stats.flatMap(d=>d[key].map(p=>p.profit));const bounds=arr=>{const low=Math.min(0,...arr),high=Math.max(0,...arr),pad=(high-low||1)*.12;return {min:low<0?low-pad:0,max:high>0?high+pad:0};};const pb=bounds(values('products')),mb=bounds(values('months'));
stats.forEach((d,i)=>{const side=i?'right':'left';$(side+'Name').textContent=displayName(d.name);$(side+'Meta').textContent=d.rows.length.toLocaleString()+' transactions · '+d.products.length+' groups'+(!d.rows.length?' · No data for current filters':'');$(side+'Metrics').innerHTML=[['Revenue',fmt(d.sales)],['Profit',fmt(d.profit)],['Margin',d.margin===null?'—':d.margin.toFixed(1)+'%']].map(([label,v])=>`<div><span>${label}</span><strong>${v}</strong></div>`).join('');
const po=chartOptions(true);Object.assign(po.scales.x,pb);po.plugins.tooltip.callbacks.label=c=>d.name+': '+fmt(c.parsed.x);const pm=new Map(d.products.map(p=>[p.name,p.profit]));buildChart(i?'pairRightProducts':'pairLeftProducts','bar',{labels:names,datasets:[{data:names.map(n=>pm.has(n)?pm.get(n):null),backgroundColor:d.color+'bb',borderRadius:4,barThickness:12}]},po);
const mo=chartOptions();Object.assign(mo.scales.y,mb);mo.scales.x.ticks.maxTicksLimit=6;const mm=new Map(d.months.map(m=>[m.name,m.profit]));buildChart(i?'pairRightMonths':'pairLeftMonths','bar',{labels:months.map(m=>new Date(m+'-01T12:00:00').toLocaleDateString('en-US',{month:'short',year:'2-digit'})),datasets:[{data:months.map(m=>mm.has(m)?mm.get(m):null),backgroundColor:d.color+'bb',borderRadius:4}]},mo);});}

let reportPdfUrl=null;
$('downloadPdf').onclick=()=>{
const button=$('downloadPdf'),status=$('pdfStatus');
if(!window.jspdf?.jsPDF){status.textContent='PDF library unavailable. Check your connection and refresh.';return;}
button.disabled=true;$('pdfDownloadActions').hidden=true;status.textContent='Preparing your PDF…';
try{
// Generate during the click event so browsers retain the download user gesture.
const comparison=comparing;
const files=comparison?[...comparisonIds].map(id=>datasets.find(d=>d.id===id)).filter(Boolean):datasets.filter(d=>d.id===activeId);
const region=$('regionFilter').value,year=$('yearFilter').value;
const pdf=new window.jspdf.jsPDF({unit:'mm',format:'a4'});
const pageWidth=210,margin=17,width=pageWidth-2*margin;let y=20;
const safe=s=>String(s).replace(/−/g,'-').replace(/[—–]/g,' - ').replace(/→/g,' to ').replace(/↔/g,' / ').replace(/✧/g,'');
const page=()=>{pdf.addPage();y=20;};
const room=h=>{if(y+h>278)page();};
const text=(s,size=10,color=[66,71,90],bold=false)=>{pdf.setFont('helvetica',bold?'bold':'normal');pdf.setFontSize(size);pdf.setTextColor(...color);const lines=pdf.splitTextToSize(safe(s),width);const lineHeight=size*.46;for(const line of lines){room(lineHeight+2);pdf.text(line,margin,y);y+=lineHeight;}y+=3;};
const heading=s=>{room(17);y+=4;text(s,13,[40,34,63],true);};
pdf.setProperties({title:'Profit Portfolio Analyzer - '+(comparison?'Comparison':currentName),subject:'Browser-generated portfolio analysis',creator:'Profit Portfolio Analyzer'});
text('PROFIT PORTFOLIO ANALYZER',10,[117,87,175],true);
text(comparison?'Portfolio comparison':'Portfolio analysis',23,[30,26,44],true);
text(files.map(d=>displayName(d.name)).join(' vs '),12,[60,52,81],true);
text('Generated: '+new Date().toLocaleString()+' | Region: '+(region||'All regions')+' | Period: '+(year||'All time'),9);
text('Grouping: '+groupLabel()+ ' | Category: '+($('categoryFilter').value||'All')+' | Sub-category: '+($('subcategoryFilter').value||'All')+' | Segment: '+($('segmentFilter').value||'All'),9);
text('All amounts displayed in USD. Files are analyzed separately and are not deduplicated. Compare matching currencies and time ranges.',9);
heading('Performance overview');
files.forEach(d=>{const rows=filteredRows(d.rows);const sales=rows.reduce((n,r)=>n+r.sales,0),profit=rows.reduce((n,r)=>n+r.profit,0);room(32);text(displayName(d.name),11,[55,44,78],true);text('Revenue: '+fmt(sales)+'   |   Profit: '+fmt(profit)+'   |   Margin: '+(sales?(profit/sales*100).toFixed(1)+'%':'N/A'),10);text(rows.length.toLocaleString()+' transactions | '+new Set(rows.map(r=>r.product)).size+' groups',9);});
if(comparison&&files.length===2){heading('Right compared with left (B - A)');text($('pairDelta').innerText,10);}
heading('Key findings');
const summary=$(comparison?'comparisonSummary':'summary');
for(const block of summary.children){const h=block.querySelector('h3'),p=block.querySelector('p');if(h)text(h.textContent,10,[55,44,78],true);if(p)text(p.textContent,10);}
const singleCharts=[['singleWorldMap','World map - dataset regions'],['bubbleChart','Sales vs profit - product portfolio'],['topChart','Top 10 products by profit'],['bottomChart','Bottom 10 products by profit'],['regionChart','Profit by region'],['monthChart','Profit by month']];
const multiCharts=[['comparisonWorldMap','World map - dataset regions'],['compareTotals','Revenue and profit comparison'],['compareProducts','Product profit comparison'],['compareRegions','Regional profit comparison'],['compareMonths','Monthly profit comparison']];
const pairCharts=files.length===2?[[ 'pairLeftProducts','A: '+displayName(files[0].name)+' - product profit'],['pairRightProducts','B: '+displayName(files[1].name)+' - product profit'],['pairLeftMonths','A: '+displayName(files[0].name)+' - monthly profit'],['pairRightMonths','B: '+displayName(files[1].name)+' - monthly profit']]:[];
const list=comparison?[...pairCharts,...multiCharts]:singleCharts;
page();text('Charts & visual analysis',18,[30,26,44],true);
for(const [id,title] of list){const chart=charts[id];if(!chart||!chart.canvas.width||!chart.canvas.height)continue;const source=chart.canvas;if(!source.getClientRects().length)continue;chart.stop();chart.update('none');const height=Math.min(100,Math.max(65,width*source.height/source.width));room(height+20);text(title,11,[55,44,78],true);const canvas=document.createElement('canvas');canvas.width=source.width;canvas.height=source.height;const ctx=canvas.getContext('2d');ctx.fillStyle='#14171f';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(source,0,0);pdf.addImage(canvas.toDataURL('image/png'),'PNG',margin,y,width,height);y+=height+12;}
const pages=pdf.getNumberOfPages();for(let i=1;i<=pages;i++){pdf.setPage(i);pdf.setFontSize(8);pdf.setFont('helvetica','normal');pdf.setTextColor(130,130,145);pdf.text('Profit Portfolio Analyzer | Private, browser-generated report',margin,289);pdf.text(i+' / '+pages,pageWidth-margin,289,{align:'right'});}
const name=(comparison?files.map(d=>d.name.replace(/\.csv$/i,'')).join('-vs-'):currentName.replace(/\.csv$/i,'')).replace(/[^a-z0-9_-]+/gi,'-').slice(0,130);
const blob=pdf.output('blob');
if(reportPdfUrl)URL.revokeObjectURL(reportPdfUrl);
reportPdfUrl=URL.createObjectURL(blob);
const save=$('savePdfLink');save.href=reportPdfUrl;save.download='profit-report-'+name+'.pdf';
$('openPdfLink').href=reportPdfUrl;$('pdfDownloadActions').hidden=false;
status.textContent='PDF ready. If no download started, click Save PDF or Open PDF above.';
save.click();
}catch(error){console.error('PDF export failed',error);status.textContent='Could not create PDF: '+(error.message||'Unknown error')+'. Please refresh and try again.';}finally{button.disabled=false;}
};

function groupLabel(){return {product:'Product',category:'Category',subcategory:'Sub-category'}[$('groupBy').value]||'Product';}
function filteredRows(input){const group=$('groupBy').value||'product';return input.filter(r=>(!$('regionFilter').value||r.region===$('regionFilter').value)&&(!$('yearFilter').value||r.month.startsWith($('yearFilter').value))&&(!$('categoryFilter').value||r.category===$('categoryFilter').value)&&(!$('subcategoryFilter').value||r.subcategory===$('subcategoryFilter').value)&&(!$('segmentFilter').value||r.segment===$('segmentFilter').value)).map(r=>({...r,product:group==='product'?r.product:r[group]||'Unspecified '+groupLabel().toLowerCase()}));}
function updateGroupingContext(){$('analysisContext').textContent='Charts grouped by '+groupLabel().toLowerCase()+'. Sales and profit sum order lines; filters apply to all views and PDF reports.';}
for(const id of ['groupBy','categoryFilter','subcategoryFilter','segmentFilter'])$(id).onchange=render;
$('superstoreBtn').onclick=async()=>{const existing=datasets.find(d=>d.name==='Sample - Superstore.csv');if(existing){activateDataset(existing.id);return;}const button=$('superstoreBtn');button.disabled=true;try{const response=await fetch('sample-data/superstore.csv');if(!response.ok)throw Error('File could not be loaded');const blob=await response.blob();importQueue.push(new File([blob],'Sample - Superstore.csv',{type:'text/csv'}));if(!importing)nextImport();}catch(error){notify('Unable to load Superstore data. Upload the CSV directly. '+error.message);}finally{button.disabled=false;}};

