function ppa3Breakdown(views,parent,field,label,metric,ranking=false){const totals=ppa3Totals(views,field,metric);if(!totals.length)return;const card=ppa3Card(parent,(metric==='sales'?'Sales':'Profit')+' by '+label,'Grouped by '+label.toLowerCase()+'. Files stay separate; absent groups are gaps, not zeros.');let mode=ranking?'top':'all';const draw=()=>{const keys=[...new Set(totals.flatMap(t=>[...t.values.keys()]))];const score=key=>totals.reduce((n,t)=>n+(t.values.get(key)||0),0);keys.sort((a,b)=>score(b)-score(a)||String(a).localeCompare(String(b)));const labels=mode==='top'?keys.slice(0,10):mode==='bottom'?keys.slice().reverse().slice(0,10):keys;card.box.style.height=Math.max(280,Math.min(1400,labels.length*25+60))+'px';const options=ppa3Options(true);options.scales.x.beginAtZero=true;ppa3Chart(card,'bar',{labels,datasets:totals.map(({view,values})=>({label:displayName(view.name),data:labels.map(key=>values.has(key)?values.get(key):null),backgroundColor:view.color+'aa',borderColor:view.color,borderWidth:1,borderRadius:3,maxBarThickness:16}))},options);};ppa3Select(card.controls,'Show',[...(ranking?[]:[['all','All groups']]),['top','Top 10'],['bottom','Bottom 10']],value=>{mode=value;draw();});draw();}
function ppa3Rankings(views,parent,field,label){const usable=views.filter(v=>v.rows.some(r=>r[field]));if(!usable.length)return;const totals=usable.map(view=>{const groups=ppa3Groups(view.rows.filter(r=>r[field]),field==='city'?r=>[r.city,r.state,r.country].filter(Boolean).join(', '):field),values=new Map(),names=new Map();for(const [key,rows] of groups){values.set(key,ppa3Sum(rows,'profit'));names.set(key,field==='customerId'?(rows.find(r=>r.customerName)?.customerName||key)+' ['+key+']':key);}return {view,values,names};});const card=ppa3Card(parent,label+' profit rankings','Top or bottom 10 by combined profit in the selected files. Customer identities use IDs, not names.');let mode='top';const draw=()=>{let labels=[...new Set(totals.flatMap(v=>[...v.values.keys()]))];const score=key=>totals.reduce((n,v)=>n+(v.values.get(key)||0),0);labels.sort((a,b)=>(mode==='top'?score(b)-score(a):score(a)-score(b))||String(a).localeCompare(String(b)));labels=labels.slice(0,10);const options=ppa3Options(true);options.scales.x.beginAtZero=true;ppa3Chart(card,'bar',{labels:labels.map(key=>totals.find(v=>v.names.has(key)).names.get(key)),datasets:totals.map(v=>({label:displayName(v.view.name),data:labels.map(key=>v.values.has(key)?v.values.get(key):null),backgroundColor:v.view.color+'aa',borderRadius:4,maxBarThickness:17}))},options);};ppa3Select(card.controls,'Rank',[['top','Top 10'],['bottom','Bottom 10']],value=>{mode=value;draw();});draw();}
function ppa3CrossBars(views,parent){for(const view of views){const categoryRows=view.rows.filter(r=>r.category&&r.region);if(categoryRows.length){const regions=[...new Set(categoryRows.map(r=>r.region))].sort(),categories=[...new Set(categoryRows.map(r=>r.category))].sort();const card=ppa3Card(parent,'Category × Region — '+displayName(view.name),'Profit by category, grouped by region.');const options=ppa3Options();options.scales.y.beginAtZero=true;ppa3Chart(card,'bar',{labels:categories,datasets:regions.map((region,i)=>({label:region,data:categories.map(category=>{const rows=categoryRows.filter(r=>r.region===region&&r.category===category);return rows.length?ppa3Sum(rows,'profit'):null;}),backgroundColor:ppa3Palette[i%ppa3Palette.length]+'b0',borderRadius:3}))},options);}
const segmentRows=view.rows.filter(r=>r.segment&&r.region);if(segmentRows.length){const regions=[...new Set(segmentRows.map(r=>r.region))].sort(),segments=[...new Set(segmentRows.map(r=>r.segment))].sort();const card=ppa3Card(parent,'Segment within Region — '+displayName(view.name),'Stacked sales by customer segment. Negative sales remain negative.');const options=ppa3Options();options.scales.x.stacked=true;options.scales.y.stacked=true;options.scales.y.beginAtZero=true;ppa3Chart(card,'bar',{labels:regions,datasets:segments.map((segment,i)=>({label:segment,data:regions.map(region=>ppa3Sum(segmentRows.filter(r=>r.region===region&&r.segment===segment),'sales')),backgroundColor:ppa3Palette[i%ppa3Palette.length]+'b0'}))},options);}}}
