function ppa5Number(value){if(value===null||value===undefined||String(value).trim()==='')return null;const number=Number(String(value).replace(/%$/,''));return Number.isFinite(number)?number:null;}
function ppa5Sum(rows,key){return rows.reduce((n,r)=>n+(Number.isFinite(r[key])?r[key]:0),0);}
function ppa5Groups(rows,key){const groups=new Map();for(const row of rows){const value=typeof key==='function'?key(row):row[key];if(value===null||value===undefined||value==='')continue;if(!groups.has(value))groups.set(value,[]);groups.get(value).push(row);}return groups;}
function ppa5MonthIndex(month){if(!/^\d{4}-\d{2}$/.test(month||''))return null;const year=Number(month.slice(0,4)),m=Number(month.slice(5));return m>=1&&m<=12?year*12+m-1:null;}
function ppa5MonthKey(index){return String(Math.floor(index/12)).padStart(4,'0')+'-'+String(index%12+1).padStart(2,'0');}
function ppa5MonthLabel(month){return ppa5MonthNames[Number(month.slice(5))-1]+' '+month.slice(2,4);}
function ppa5PrepareTime(view){
// New preparation after Part 2: copy summaries; reuse its derived values.
const observed=view.monthly.filter(m=>ppa5MonthIndex(m.month)!==null).map(m=>({...m})).sort((a,b)=>a.month.localeCompare(b.month));const lookup=new Map(observed.map(m=>[m.month,m])),groups=ppa5Groups(view.rows,'month');let runningSales=0,runningProfit=0;
for(const month of observed){const rows=groups.get(month.month)||[];function existing(name,fallback){const values=[...new Set(rows.map(r=>ppa5Number(r.ppaDerived?.[name])).filter(v=>v!==null))];return values.length===1?values[0]:values.length>1?null:fallback;}
month.mom=existing('MoM Growth %',month.mom??null);month.yoy=existing('YoY Growth %',month.yoy??null);month.movingAverage=existing('Moving Average',month.movingAverage??null);const index=ppa5MonthIndex(month.month);if(!lookup.has(ppa5MonthKey(index-1))||!lookup.has(ppa5MonthKey(index-2)))month.movingAverage=null;
runningSales+=month.sales;runningProfit+=month.profit;const ordered=rows.map((row,i)=>({row,i})).sort((a,b)=>(a.row.ppaDate??0)-(b.row.ppaDate??0)||a.i-b.i);const closing=name=>{for(let i=ordered.length-1;i>=0;i--){const value=ppa5Number(ordered[i].row.ppaDerived?.[name]);if(value!==null)return value;}return null;};month.cumulativeSales=closing('Cumulative Sales')??runningSales;month.cumulativeProfit=closing('Cumulative Profit')??runningProfit;}
let timeline=observed.map(m=>m.month);if(timeline.length){const first=ppa5MonthIndex(timeline[0]),last=ppa5MonthIndex(timeline.at(-1));if(last-first<=1200)timeline=Array.from({length:last-first+1},(_,i)=>ppa5MonthKey(first+i));}
return {...view,ppa5Observed:observed,ppa5Lookup:lookup,ppa5Timeline:timeline};}
function ppa5Section(title,caption){const section=document.createElement('section');section.className='ppa5-section';const heading=document.createElement('h2');heading.textContent=title;const p=document.createElement('p');p.className='ppa5-caption';p.textContent=caption;const grid=document.createElement('div');grid.className='ppa5-grid';section.append(heading,p,grid);ppa5Root.append(section);return {section,grid};}
function ppa5Card(parent,title,caption){const article=document.createElement('article');article.className='panel ppa5-card';const heading=document.createElement('h3');heading.textContent=title;const p=document.createElement('p');p.textContent=caption;const controls=document.createElement('div');controls.className='ppa5-controls';const box=document.createElement('div');box.className='ppa5-canvas';const canvas=document.createElement('canvas');canvas.setAttribute('role','img');canvas.setAttribute('aria-label',title);box.append(canvas);article.append(heading,p,controls,box);parent.append(article);return {article,canvas,controls,box};}
function ppa5Options(){const options=chartOptions();options.animation={duration:200};options.plugins.legend={display:true,position:'bottom',labels:{color:'#adb1c5',boxWidth:9,font:{size:10}}};options.plugins.tooltip.callbacks={label:c=>c.dataset.label+': '+(c.parsed.y===null?'No data':fmt(c.parsed.y))};options.scales.x.ticks.maxTicksLimit=12;return options;}
function ppa5Chart(card,type,data,options,plugins=[]){if(card.ppa5Chart){card.ppa5Chart.destroy();ppa5Charts.delete(card.ppa5Chart);}const chart=new Chart(card.canvas,{type,data,options,plugins});card.ppa5Chart=chart;ppa5Charts.add(chart);return chart;}
function ppa5Select(card,label,choices,onChange){const container=document.createElement('label');container.textContent=label+' ';const select=document.createElement('select');choices.forEach(([value,text])=>select.add(new Option(text,value)));select.addEventListener('change',()=>onChange(select.value));container.append(select);card.controls.append(container);return select;}
function ppa5Line(label,data,color,extra={}){return {label,data,borderColor:color,backgroundColor:color+'55',borderWidth:2,pointRadius:data.length>60?0:2,pointHoverRadius:4,tension:.15,spanGaps:false,...extra};}
function ppa5Monthly(views,parent){for(const view of views){const card=ppa5Card(parent,'Monthly sales, profit & moving average — '+displayName(view.name),'Sales on the left axis, profit on the right. The existing monthly profit bar chart is not replaced. Existing 3-month sales averages are reused only for consecutive calendar months; missing months are gaps.');card.article.classList.add('ppa5-wide');const toggleLabel=document.createElement('label'),toggle=document.createElement('input');toggle.type='checkbox';toggle.checked=true;toggleLabel.append(toggle,document.createTextNode(' Show 3-month sales average'));card.controls.append(toggleLabel);const draw=()=>{const months=view.ppa5Timeline;const datasets=[ppa5Line('Sales',months.map(m=>view.ppa5Lookup.get(m)?.sales??null),view.color,{yAxisID:'y'}),ppa5Line('Profit',months.map(m=>view.ppa5Lookup.get(m)?.profit??null),'#54d6b3',{yAxisID:'profit',borderDash:[5,3]})];if(toggle.checked)datasets.push(ppa5Line('Sales · 3-month moving average',months.map(m=>view.ppa5Lookup.get(m)?.movingAverage??null),'#edbd6c',{yAxisID:'y',borderDash:[2,4],pointRadius:0}));const options=ppa5Options();options.scales.y.title={display:true,text:'Sales ($)',color:'#858a9e',font:{size:10}};options.scales.profit={type:'linear',position:'right',border:{display:false},grid:{drawOnChartArea:false},ticks:{color:'#54d6b3',font:{size:9},callback:v=>compact(v)},title:{display:true,text:'Profit ($)',color:'#54d6b3',font:{size:10}}};ppa5Chart(card,'line',{labels:months.map(ppa5MonthLabel),datasets},options);};toggle.addEventListener('change',draw);draw();}}
function ppa5YearQuarter(views,parent){for(const mode of ['Year','Quarter']){const results=views.map(view=>{const rows=view.rows.filter(r=>r.month);const groups=ppa5Groups(rows,row=>{const year=String(row.ppaDerived?.Year??row.month.slice(0,4));if(mode==='Year')return /^\d{4}$/.test(year)?year:null;const raw=String(row.ppaDerived?.Quarter??'').toUpperCase();const match=raw.match(/^(?:Q)?([1-4])$/);return /^\d{4}$/.test(year)&&match?year+' Q'+match[1]:null;});return {view,groups};}).filter(s=>s.groups.size);if(!results.length)continue;const labels=[...new Set(results.flatMap(s=>[...s.groups.keys()]))].sort();const card=ppa5Card(parent,mode==='Year'?'Yearly sales & profit':'Quarterly trend','Sales and profit totals by '+mode.toLowerCase()+'. Existing Year / Quarter derived fields are reused. Missing groups remain gaps.');const datasets=results.flatMap(({view,groups})=>[ppa5Line(displayName(view.name)+' · Sales',labels.map(key=>groups.has(key)?ppa5Sum(groups.get(key),'sales'):null),view.color),ppa5Line(displayName(view.name)+' · Profit',labels.map(key=>groups.has(key)?ppa5Sum(groups.get(key),'profit'):null),view.color,{borderDash:[5,4]})]);ppa5Chart(card,'line',{labels,datasets},ppa5Options());}}
function ppa5CategoryArea(views,parent){for(const view of views){const rows=view.rows.filter(r=>r.category&&r.month);if(!rows.length)continue;const groups=[...ppa5Groups(rows,'category')].map(([name,lines])=>({name,total:ppa5Sum(lines,'sales')})).sort((a,b)=>b.total-a.total);const top=groups.slice(0,8).map(g=>g.name),other=groups.slice(8).map(g=>g.name);const categories=[...top,...(other.length?['Other categories']:[])];const card=ppa5Card(parent,'Category sales over time — '+displayName(view.name),'Stacked monthly sales area. '+(other.length?'Top 8 categories shown; remaining categories are combined as Other. ':'')+'Missing months remain gaps.');const datasets=categories.map((name,i)=>ppa5Line(name,view.ppa5Timeline.map(month=>{if(!view.ppa5Lookup.has(month))return null;const lines=rows.filter(r=>r.month===month&&(name==='Other categories'?other.includes(r.category):r.category===name));return lines.length?ppa5Sum(lines,'sales'):0;}),ppa5Palette[i%ppa5Palette.length],{fill:true,stack:'categorySales',pointRadius:0,borderWidth:1,backgroundColor:ppa5Palette[i%ppa5Palette.length]+'70'}));const options=ppa5Options();options.scales.y.stacked=true;options.scales.y.beginAtZero=true;ppa5Chart(card,'line',{labels:view.ppa5Timeline.map(ppa5MonthLabel),datasets},options);}}
function ppa5DimensionLines(views,parent){for(const view of views){for(const [field,label] of [['region','Region'],['segment','Segment']]){const rows=view.rows.filter(r=>r[field]&&r.month);if(!rows.length)continue;const names=[...ppa5Groups(rows,field)].sort((a,b)=>ppa5Sum(b[1],'sales')-ppa5Sum(a[1],'sales')).slice(0,8).map(([name])=>name);const card=ppa5Card(parent,'Monthly trend by '+label+' — '+displayName(view.name),'Separate lines within this file; up to 8 groups ranked by filtered sales. Missing group-month observations are gaps, not invented zeros.');let metric='sales';const draw=()=>{const options=ppa5Options();options.scales.y.title={display:true,text:metric==='sales'?'Sales ($)':'Profit ($)',color:'#858a9e',font:{size:10}};ppa5Chart(card,'line',{labels:view.ppa5Timeline.map(ppa5MonthLabel),datasets:names.map((name,i)=>ppa5Line(name,view.ppa5Timeline.map(month=>{const lines=rows.filter(r=>r.month===month&&r[field]===name);return lines.length?ppa5Sum(lines,metric):null;}),ppa5Palette[i%ppa5Palette.length]))},options);};ppa5Select(card,'Metric',[['sales','Sales'],['profit','Profit']],value=>{metric=value;draw();});draw();}}}
const ppa5HeatPlugin={id:'ppa5TimeHeatCells',afterDatasetsDraw(chart){const {ctx,scales:{x,y}}=chart,dataset=chart.data.datasets[0];if(!dataset)return;const width=Math.abs(x.getPixelForValue(1)-x.getPixelForValue(0)),height=Math.abs(y.getPixelForValue(1)-y.getPixelForValue(0));ctx.save();for(const point of dataset.data){if(point.v===null)continue;const alpha=.14+.8*Math.min(1,Math.abs(point.v)/(dataset.ppa5Maximum||1));ctx.fillStyle='rgba('+(point.v<0?'239,131,149':dataset.ppa5Negative?'84,214,179':'172,153,255')+','+alpha+')';ctx.fillRect(x.getPixelForValue(point.x)-width/2+.7,y.getPixelForValue(point.y)-height/2+.7,Math.max(1,width-1.4),Math.max(1,height-1.4));}ctx.restore();}};
function ppa5Heat(card,xLabels,yLabels,cells,metric,calendar=false){const values=cells.filter(c=>c.v!==null).map(c=>c.v),maximum=Math.max(1,...values.map(Math.abs)),negative=values.some(v=>v<0);const options=ppa5Options();options.animation=false;options.plugins.legend={display:false};options.scales={x:{type:'linear',min:-.5,max:xLabels.length-.5,grid:{display:false},border:{display:false},ticks:{stepSize:1,maxTicksLimit:calendar?13:12,color:'#929bb2',font:{size:9},callback:v=>Number.isInteger(v)?xLabels[v]||'':''}},y:{type:'linear',min:-.5,max:yLabels.length-.5,reverse:true,grid:{display:false},border:{display:false},ticks:{stepSize:1,autoSkip:false,color:'#929bb2',font:{size:9},callback:v=>Number.isInteger(v)?yLabels[v]||'':''}}};options.interaction={mode:'nearest',intersect:false};options.plugins.tooltip.callbacks={title:items=>{const cell=items[0]?.raw;return cell?cell.date||yLabels[cell.y]+' '+xLabels[cell.x]:'';},label:context=>context.raw.v===null?'No observed order lines':[(metric==='sales'?'Sales: ':'Profit: ')+fmt(context.raw.v),'Order lines: '+context.raw.count]};ppa5Chart(card,'scatter',{datasets:[{data:cells,pointRadius:0,pointHitRadius:10,ppa5Maximum:maximum,ppa5Negative:negative}]},options,[ppa5HeatPlugin]);let legend=card.article.querySelector('.ppa5-heat-key');if(!legend){legend=document.createElement('p');legend.className='ppa5-heat-key';card.article.append(legend);}legend.textContent=(negative?'Rose = negative · Mint = positive. ':'Brighter purple = higher values. ')+'Unfilled cells have no observed order lines; observed zero values remain filled.';}
function ppa5DailyCells(rows,year,metric='sales'){const first=Date.UTC(year,0,1),last=Date.UTC(year,11,31),offset=(new Date(first).getUTCDay()+6)%7,start=first-offset*86400000,weeks=Math.floor((last-start)/86400000/7)+1;const groups=ppa5Groups(rows.filter(r=>r.ppaDate!==null&&new Date(r.ppaDate).getUTCFullYear()===year),r=>r.ppaDate);const cells=[];for(let stamp=first;stamp<=last;stamp+=86400000){const lines=groups.get(stamp),days=Math.round((stamp-start)/86400000);cells.push({x:Math.floor(days/7),y:days%7,v:lines?ppa5Sum(lines,metric):null,count:lines?.length||0,date:new Date(stamp).toISOString().slice(0,10)});}return {cells,weeks,start};}
function ppa5Calendars(views,parent){for(const view of views){const dated=view.rows.filter(r=>r.ppaDate!==null);if(!dated.length)continue;const years=[...new Set(dated.map(r=>new Date(r.ppaDate).getUTCFullYear()))].sort((a,b)=>a-b);const card=ppa5Card(parent,'Daily calendar — '+displayName(view.name),'Daily totals from exact order dates. Monday-first weeks; blank days are unobserved, not assumed zero. Select a year independently of the existing filters.');card.article.classList.add('ppa5-wide');card.box.style.height='240px';let year=years.at(-1),metric='sales';const draw=()=>{const result=ppa5DailyCells(dated,year,metric);const labels=Array.from({length:result.weeks},(_,i)=>{const date=new Date(result.start+i*7*86400000);return ppa5MonthNames[date.getUTCMonth()]+' '+date.getUTCDate();});ppa5Heat(card,labels,['Mon','Tue','Wed','Thu','Fri','Sat','Sun'],result.cells,metric,true);};const select=ppa5Select(card,'Year',years.map(y=>[String(y),String(y)]),value=>{year=Number(value);draw();});select.value=String(year);ppa5Select(card,'Metric',[['sales','Sales'],['profit','Profit']],value=>{metric=value;draw();});draw();}}
function ppa5YearMonth(views,parent){for(const view of views){const years=[...new Set(view.ppa5Observed.map(m=>m.month.slice(0,4)))].sort();if(!years.length)continue;const card=ppa5Card(parent,'Year × Month — '+displayName(view.name),'Seasonal totals by calendar year and month. Unlike the existing State × Month heatmap, rows represent years. Missing months are unfilled.');card.box.style.height=Math.max(240,years.length*37+75)+'px';const monthGroups=ppa5Groups(view.rows,'month');let metric='sales';const draw=()=>{const cells=[];years.forEach((year,j)=>{for(let i=0;i<12;i++){const month=view.ppa5Lookup.get(year+'-'+String(i+1).padStart(2,'0'));cells.push({x:i,y:j,v:month?month[metric]:null,count:month?(monthGroups.get(month.month)||[]).length:0});}});ppa5Heat(card,ppa5MonthNames,years,cells,metric);};ppa5Select(card,'Metric',[['sales','Sales'],['profit','Profit']],value=>{metric=value;draw();});draw();}}
function ppa5Weekdays(views,parent){const labels=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'];for(const view of views){const groups=ppa5Groups(view.rows,r=>{const value=String(r.ppaDerived?.Weekday||'').toLowerCase();return labels.find(day=>day.toLowerCase()===value||day.slice(0,3).toLowerCase()===value)||null;});if(!groups.size)continue;const card=ppa5Card(parent,'Weekday performance — '+displayName(view.name),'Totals by existing derived Weekday values. These are totals, not per-day averages; weekday exposure can differ.');const options=ppa5Options();options.scales.y.beginAtZero=true;ppa5Chart(card,'bar',{labels,datasets:[{label:'Sales',data:labels.map(day=>groups.has(day)?ppa5Sum(groups.get(day),'sales'):null),backgroundColor:view.color+'bb',borderRadius:3},{label:'Profit',data:labels.map(day=>groups.has(day)?ppa5Sum(groups.get(day),'profit'):null),backgroundColor:'#54d6b3bb',borderRadius:3}]},options);}}
function ppa5Growth(views,parent){for(const view of views){if(!view.ppa5Observed.some(m=>m.mom!==null||m.yoy!==null))continue;const card=ppa5Card(parent,'Sales growth — '+displayName(view.name),'Reuses existing MoM / YoY derived growth. Green = growth; red = decline. No bar when the matching previous calendar period is absent or its sales are zero. Partial periods are not adjusted.');let mode='mom';const draw=()=>{const values=view.ppa5Timeline.map(month=>view.ppa5Lookup.get(month)?.[mode]??null);const options=ppa5Options();options.plugins.legend={display:false};options.scales.y.ticks.callback=v=>v+'%';options.plugins.tooltip.callbacks={label:c=>(mode==='mom'?'MoM':'YoY')+': '+c.parsed.y.toFixed(2)+'%'};ppa5Chart(card,'bar',{labels:view.ppa5Timeline.map(ppa5MonthLabel),datasets:[{label:mode==='mom'?'MoM sales growth':'YoY sales growth',data:values,backgroundColor:values.map(v=>v<0?'#ef8395bb':'#54d6b3bb'),borderRadius:3}]},options);};ppa5Select(card,'Period',[['mom','Month over month'],['yoy','Year over year']],value=>{mode=value;draw();});draw();}}
function ppa5Cumulative(views,parent){const allMonths=[...new Set(views.flatMap(v=>v.ppa5Timeline))].sort();if(!allMonths.length)return;const card=ppa5Card(parent,'Cumulative sales & profit','Uses existing cumulative fields at each month close. Only when those fields are missing, this add-on computes filtered monthly running totals. Source-provided cumulative fields retain their original scope. Missing months are gaps.');card.article.classList.add('ppa5-wide');const datasets=views.flatMap(view=>[ppa5Line(displayName(view.name)+' · Cumulative sales',allMonths.map(m=>view.ppa5Lookup.get(m)?.cumulativeSales??null),view.color),ppa5Line(displayName(view.name)+' · Cumulative profit',allMonths.map(m=>view.ppa5Lookup.get(m)?.cumulativeProfit??null),view.color,{borderDash:[5,4]})]);ppa5Chart(card,'line',{labels:allMonths.map(ppa5MonthLabel),datasets},ppa5Options());}
function ppa5Ranks(view,count=5){const groups=[...ppa5Groups(view.rows.filter(r=>r.product&&r.month),'product')].map(([name,rows])=>({name,total:ppa5Sum(rows,'sales')})).sort((a,b)=>b.total-a.total||a.name.localeCompare(b.name));const selected=groups.slice(0,count).map(g=>g.name),rankings=new Map();for(const month of view.ppa5Timeline){const rows=view.rows.filter(r=>r.month===month);const ranked=[...ppa5Groups(rows,'product')].map(([name,lines])=>({name,sales:ppa5Sum(lines,'sales')})).sort((a,b)=>b.sales-a.sales||a.name.localeCompare(b.name));rankings.set(month,new Map(ranked.map((r,i)=>[r.name,i+1])));}return {selected,rankings};}
function ppa5Bumps(views,parent){for(const view of views){if(new Set(view.rows.map(r=>r.product)).size<2||view.ppa5Observed.length<2)continue;const card=ppa5Card(parent,'Ranking over time — '+displayName(view.name),'Bump chart for the top overall sales groups, using the existing Analyze by grouping. Each month ranks against all observed groups; ties use name order. Absent groups are gaps, not last place.');let count=5;const draw=()=>{const result=ppa5Ranks(view,count),options=ppa5Options();options.scales.y.reverse=true;options.scales.y.min=1;options.scales.y.ticks.callback=v=>Number.isInteger(v)?'#'+v:'';options.scales.y.ticks.precision=0;options.scales.y.title={display:true,text:'Monthly sales rank · 1 is highest',color:'#858a9e',font:{size:10}};options.plugins.tooltip.callbacks={label:c=>c.dataset.label+': rank '+c.parsed.y};ppa5Chart(card,'line',{labels:view.ppa5Timeline.map(ppa5MonthLabel),datasets:result.selected.map((name,i)=>ppa5Line(name,view.ppa5Timeline.map(month=>result.rankings.get(month)?.get(name)??null),ppa5Palette[i%ppa5Palette.length],{tension:0}))},options);};ppa5Select(card,'Groups',[['5','Top 5 overall'],['10','Top 10 overall']],value=>{count=Number(value);draw();});draw();}}
function ppa5Render(){if(!ppa5Root)return;for(const chart of ppa5Charts)chart.destroy();ppa5Charts.clear();ppa5Root.replaceChildren();const views=window.PPAAdditions.views().map(ppa5PrepareTime).filter(v=>v.ppa5Observed.length);if(!views.length)return;const trends=ppa5Section('Time intelligence: trends & smoothing','Part 5 · All views follow the existing file selection, grouping and filters. Missing time periods are not silently treated as zero.');ppa5Monthly(views,trends.grid);ppa5YearQuarter(views,trends.grid);ppa5CategoryArea(views,trends.grid);ppa5DimensionLines(views,trends.grid);const seasonal=ppa5Section('Seasonality & calendar','Exact dates are required for daily calendars and weekday views; monthly-only files still support year–month analysis.');ppa5Calendars(views,seasonal.grid);ppa5YearMonth(views,seasonal.grid);ppa5Weekdays(views,seasonal.grid);if(!seasonal.grid.children.length)seasonal.section.remove();const momentum=ppa5Section('Growth, cumulative performance & changing ranks','These views add rate-of-change and ranking information without replacing the existing monthly profit charts.');ppa5Growth(views,momentum.grid);ppa5Cumulative(views,momentum.grid);ppa5Bumps(views,momentum.grid);if(!momentum.grid.children.length)momentum.section.remove();}
