function ppa5Initialize(){if(document.getElementById('ppa-additions-part5')||!window.PPAAdditions)return;const anchor=document.getElementById('ppa-additions-part4')||document.getElementById('ppa-additions-part3')||document.getElementById('ppa-additions');if(!anchor)return;ppa5Root=document.createElement('div');ppa5Root.id='ppa-additions-part5';anchor.after(ppa5Root);ppa5Root.addEventListener('click',event=>event.stopPropagation());ppa5Root.addEventListener('change',event=>event.stopPropagation());const observer=new MutationObserver(ppa5Schedule);observer.observe(document.getElementById('ppa-additions'),{childList:true});ppa5Schedule();}
