function ppa7Render(){if(!ppa7Root)return;for(const chart of ppa7Charts)chart.destroy();ppa7Charts.clear();ppa7Root.replaceChildren();const views=window.PPAAdditions.views();if(!views.some(v=>v.rows.length))return;const shipping=ppa7Section('Shipping operations','Part 7 · Prepared shipping durations, filtered order lines, and no changes to existing KPIs or charts.');ppa7ShippingCharts(views,shipping.grid);if(!shipping.grid.children.length)shipping.section.remove();const advanced=ppa7Section('Advanced diagnostics & business flows','Waterfalls reconcile profit; Sankey ribbons show sales composition, not conversion. Radar scales are normalized, not a performance score.');ppa7Waterfalls(views,advanced.grid);ppa7Sankeys(views,advanced.grid);ppa7Radar(views,advanced.grid);ppa7ProfitRanges(views,advanced.grid);ppa7Outliers(views,advanced.grid);ppa7Parallel(views,advanced.grid);if(!advanced.grid.children.length)advanced.section.remove();const supplied=ppa7Section('Source-provided stages & targets','Only explicit stage counts and sales-target fields activate these charts. No sales funnel or target is invented from Superstore data.');ppa7FunnelsAndBullets(views,supplied.grid);if(!supplied.grid.children.length)supplied.section.remove();const geography=ppa7Section('Detailed geography: states & cities','Existing world-region maps remain unchanged. New maps use verified state boundaries and city coordinates, with unmatched locations omitted explicitly.');ppa7StateMaps(views,geography.grid);ppa7CityMaps(views,geography.grid);if(!geography.grid.children.length)geography.section.remove();}
function ppa7Schedule(){if(ppa7Frame!==null)return;ppa7Frame=requestAnimationFrame(()=>{ppa7Frame=null;try{ppa7Render();}catch(error){console.error('Part 7 add-on failed',error);const message=document.createElement('p');message.textContent='Some Part 7 charts could not render. Existing analysis remains unchanged.';ppa7Root.append(message);}});}
function ppa7Initialize(){if(document.getElementById('ppa-additions-part7')||!window.PPAAdditions)return;const anchor=document.getElementById('ppa-additions-part6')||document.getElementById('ppa-additions-part5')||document.getElementById('ppa-additions');if(!anchor)return;ppa7Root=document.createElement('div');ppa7Root.id='ppa-additions-part7';anchor.after(ppa7Root);ppa7Root.addEventListener('click',event=>event.stopPropagation());ppa7Root.addEventListener('change',event=>event.stopPropagation());ppa7Root.addEventListener('input',event=>event.stopPropagation());const observer=new MutationObserver(ppa7Schedule);observer.observe(document.getElementById('ppa-additions'),{childList:true});ppa7Schedule();}

